import type { ServicePage } from "@/types";

const customLmsFaqs: ServicePage["faqs"] = [
  { question: { en: "How much does custom LMS development cost?", fr: "Combien coûte le développement d'un LMS sur mesure ?", es: "¿Cuánto cuesta desarrollar un LMS a medida?", de: "Was kostet die Entwicklung eines maßgeschneiderten LMS?" }, answer: { en: "It depends on the hard parts: how many distinct learner flows, how much data you're migrating, the integrations, and the reporting you actually need. We scope a narrow first release with a clear second step and share the assumptions in the open, then quote the specific piece of work. A number without those details is a delayed surprise.", fr: "Cela dépend des points difficiles : le nombre de parcours apprenants, le volume de données à migrer, les intégrations et le reporting dont vous avez réellement besoin. Nous cadrons une première version limitée avec une deuxième étape claire et partageons les hypothèses avant de chiffrer le travail précis. Un montant sans ces détails devient une surprise différée.", es: "Depende de las partes difíciles: cuántos recorridos de alumnos hay, qué volumen de datos se migra, las integraciones y los informes que realmente necesitas. Definimos una primera versión acotada con un segundo paso claro y compartimos las hipótesis antes de presupuestar el trabajo concreto. Una cifra sin esos detalles es una sorpresa aplazada.", de: "Es hängt von den schwierigen Teilen ab: wie viele unterschiedliche Lernabläufe es gibt, wie viele Daten migriert werden, welche Integrationen nötig sind und welches Reporting Sie wirklich brauchen. Wir grenzen eine erste Version mit einem klaren zweiten Schritt ab und legen die Annahmen offen, bevor wir die konkrete Arbeit bepreisen. Eine Zahl ohne diese Details ist eine verspätete Überraschung." } },
  { question: { en: "How long until the first release?", fr: "Quel délai pour une première version ?", es: "¿Cuánto falta para la primera versión?", de: "Wie lange dauert es bis zur ersten Version?" }, answer: { en: "Most focused platforms are usable in 8 to 12 weeks. We work in weekly slices, so you're clicking through the real thing early instead of waiting months for a slide deck.", fr: "La plupart des plateformes ciblées sont utilisables en 8 à 12 semaines. Nous avançons par livraisons hebdomadaires, afin que vous puissiez essayer le vrai produit tôt au lieu d'attendre des mois une présentation.", es: "La mayoría de las plataformas enfocadas se pueden usar en 8 a 12 semanas. Trabajamos en entregas semanales para que pruebes el producto real pronto, en vez de esperar meses una presentación.", de: "Die meisten fokussierten Plattformen sind in 8 bis 12 Wochen nutzbar. Wir arbeiten in wöchentlichen Schritten, sodass Sie das echte Produkt früh ausprobieren können, statt Monate auf eine Präsentation zu warten." } },
  { question: { en: "Do we own the code?", fr: "Sommes-nous propriétaires du code ?", es: "¿Somos propietarios del código?", de: "Gehört uns der Code?" }, answer: { en: "Yes. At handover you get the application code, deployment docs, and the infrastructure access we agreed in the plan. Ongoing support is available, never required.", fr: "Oui. Lors de la remise, vous recevez le code applicatif, la documentation de déploiement et les accès à l'infrastructure prévus au plan. Un support continu est possible, jamais obligatoire.", es: "Sí. En la entrega recibes el código de la aplicación, la documentación de despliegue y los accesos a la infraestructura acordados en el plan. El soporte continuo está disponible, pero nunca es obligatorio.", de: "Ja. Bei der Übergabe erhalten Sie den Anwendungscode, die Bereitstellungsdokumentation und den im Plan vereinbarten Infrastrukturzugang. Laufender Support ist möglich, aber nie verpflichtend." } },
  { question: { en: "Can it work with the systems we already run?", fr: "Peut-il fonctionner avec les systèmes que nous utilisons déjà ?", es: "¿Puede funcionar con los sistemas que ya usamos?", de: "Kann es mit den Systemen funktionieren, die wir bereits nutzen?" }, answer: { en: "Where the API or standard supports it, yes. We confirm identity, payments, content packages, and reporting during technical discovery rather than assuming an integration is simple.", fr: "Oui, lorsque l'API ou le standard le permet. Nous confirmons l'identité, les paiements, les paquets de contenus et le reporting pendant la découverte technique au lieu de supposer qu'une intégration est simple.", es: "Sí, cuando la API o el estándar lo permite. Confirmamos identidad, pagos, paquetes de contenido e informes durante el descubrimiento técnico en lugar de dar por simple una integración.", de: "Ja, wenn API oder Standard es unterstützen. In der technischen Discovery klären wir Identität, Zahlungen, Content-Pakete und Reporting, statt eine Integration für einfach zu halten." } },
];

const corporateFaqs: ServicePage["faqs"] = [
  { question: { en: "How much does a corporate training platform cost?", fr: "Combien coûte une plateforme de formation en entreprise ?", es: "¿Cuánto cuesta una plataforma de formación corporativa?", de: "Was kostet eine Unternehmensschulungsplattform?" }, answer: { en: "The moving parts are SSO, HRIS connections, compliance evidence, partner training, and migrating historic records. We scope the reporting questions before quoting, because that is where vague requirements get expensive. Every estimate we share is tied to a specific scope, not a marketing range.", fr: "Les variables sont le SSO, les connexions HRIS, les preuves de conformité, la formation partenaire et la migration des historiques. Nous cadrons les questions de reporting avant de chiffrer, car c'est là que les exigences floues deviennent coûteuses. Chaque estimation est liée à un périmètre précis, pas à une fourchette marketing.", es: "Las variables son SSO, conexiones con HRIS, evidencia de cumplimiento, formación de socios y migración de registros históricos. Definimos las preguntas de informes antes de presupuestar, porque ahí los requisitos vagos se vuelven caros. Cada estimación se vincula a un alcance concreto, no a un rango de marketing.", de: "Die entscheidenden Faktoren sind SSO, HRIS-Anbindungen, Compliance-Nachweise, Partnerschulungen und die Migration historischer Daten. Wir klären die Reporting-Fragen vor dem Angebot, weil vage Anforderungen dort teuer werden. Jede Schätzung ist an einen konkreten Umfang gebunden, nicht an eine Marketing-Spanne." } },
  { question: { en: "How long does it take to launch?", fr: "Combien de temps faut-il pour le lancement ?", es: "¿Cuánto tarda el lanzamiento?", de: "Wie lange dauert der Launch?" }, answer: { en: "Around 8 to 12 weeks for the core, in weekly builds. Identity and role data get proven first, because a polished dashboard with the wrong access model is expensive wallpaper.", fr: "Environ 8 à 12 semaines pour le cœur, avec des versions hebdomadaires. Les données d'identité et de rôle sont prouvées en premier, car un dashboard élégant avec le mauvais modèle d'accès ne sert à rien.", es: "Unas 8 a 12 semanas para el núcleo, en entregas semanales. Primero se prueban los datos de identidad y roles, porque un panel pulido con un modelo de acceso incorrecto no sirve de nada.", de: "Etwa 8 bis 12 Wochen für den Kern, in wöchentlichen Builds. Identitäts- und Rollendaten werden zuerst bewiesen, denn ein poliertes Dashboard mit falschem Zugriffsmodell hilft nicht." } },
  { question: { en: "Will it connect to our SSO and HR systems?", fr: "Se connectera-t-elle à notre SSO et à nos systèmes RH ?", es: "¿Se conectará a nuestros sistemas de SSO y RRHH?", de: "Wird sie sich mit unserem SSO und unseren HR-Systemen verbinden?" }, answer: { en: "That's usually the point. We confirm the identity provider, the systems of record, and the exact sign-in flow during discovery, then place people into the right roles automatically instead of asking a manager to update a group by hand.", fr: "C'est généralement le but. Nous confirmons le fournisseur d'identité, les systèmes de référence et le parcours de connexion exact pendant la découverte, puis attribuons automatiquement les bons rôles au lieu de demander à un manager de mettre un groupe à jour à la main.", es: "Ese suele ser el objetivo. Confirmamos el proveedor de identidad, los sistemas de referencia y el flujo exacto de inicio de sesión durante el descubrimiento, y asignamos automáticamente a las personas los roles adecuados en vez de pedir a un responsable que actualice un grupo a mano.", de: "Das ist meist der Punkt. In der Discovery klären wir Identity Provider, führende Systeme und den genauen Login-Ablauf und weisen Menschen automatisch den richtigen Rollen zu, statt einen Manager Gruppen manuell aktualisieren zu lassen." } },
  { question: { en: "How do you handle compliance evidence and old records?", fr: "Comment gérez-vous les preuves de conformité et les anciens dossiers ?", es: "¿Cómo gestionáis la evidencia de cumplimiento y los registros antiguos?", de: "Wie gehen Sie mit Compliance-Nachweisen und alten Daten um?" }, answer: { en: "We record attempts, acknowledgement, expiry, certificates, and the version of the material a learner saw, so an audit is a report rather than a scramble. Historic records either migrate or move to a retained archive with a clear audit path, decided before cutover.", fr: "Nous enregistrons les tentatives, attestations, échéances, certificats et la version du contenu vue par l'apprenant, afin qu'un audit devienne un rapport plutôt qu'une course contre la montre. Les historiques sont migrés ou placés dans une archive conservée avec une piste d'audit claire, décision prise avant le basculement.", es: "Registramos intentos, confirmaciones, vencimientos, certificados y la versión del material que vio el alumno, para que una auditoría sea un informe y no una carrera. Los registros históricos se migran o pasan a un archivo conservado con una ruta de auditoría clara, decidido antes del cambio.", de: "Wir erfassen Versuche, Bestätigungen, Ablaufdaten, Zertifikate und die Materialversion, die ein Lernender gesehen hat, damit ein Audit ein Bericht und keine hektische Suche wird. Historische Daten werden migriert oder in ein aufbewahrtes Archiv mit klarem Prüfpfad verschoben, entschieden vor der Umstellung." } },
];

const creatorFaqs: ServicePage["faqs"] = [
  { question: { en: "How much does a custom course platform cost?", fr: "Combien coûte une plateforme de cours sur mesure ?", es: "¿Cuánto cuesta una plataforma de cursos a medida?", de: "Was kostet eine maßgeschneiderte Kursplattform?" }, answer: { en: "The cost moves with the shape of the offer: custom checkout logic, memberships, team purchasing, a catalogue migration, or a built-in community all push it up. We scope around the offer that makes money now, not the hypothetical one three years out, and quote against that specific plan.", fr: "Le coût dépend de la forme de l'offre : logique de checkout sur mesure, memberships, achats d'équipe, migration de catalogue ou communauté intégrée font tous monter le budget. Nous cadrons l'offre qui génère du revenu aujourd'hui, pas une hypothèse à trois ans, puis chiffrons ce plan précis.", es: "El coste depende de la forma de la oferta: checkout a medida, membresías, compras de equipos, migración de catálogo o comunidad integrada hacen subir el presupuesto. Definimos la oferta que genera ingresos hoy, no una hipótesis a tres años, y presupuestamos ese plan concreto.", de: "Die Kosten folgen der Form des Angebots: individueller Checkout, Mitgliedschaften, Teamkäufe, Katalogmigration oder eine integrierte Community erhöhen sie. Wir grenzen das Angebot ab, das heute Umsatz erzielt, nicht ein hypothetisches in drei Jahren, und bepreisen diesen konkreten Plan." } },
  { question: { en: "How soon can I start selling on it?", fr: "Quand puis-je commencer à vendre dessus ?", es: "¿Cuándo puedo empezar a vender en ella?", de: "Wie schnell kann ich darauf verkaufen?" }, answer: { en: "Usually 8 to 12 weeks, built in weekly slices. You can start selling once the purchase-and-delivery path is proven, before every feature is polished.", fr: "Généralement 8 à 12 semaines, avec des livraisons hebdomadaires. Vous pouvez commencer à vendre dès que le parcours d'achat et de livraison est validé, avant que chaque fonction soit parfaitement finalisée.", es: "Normalmente 8 a 12 semanas, en entregas semanales. Puedes empezar a vender cuando el flujo de compra y entrega esté probado, antes de pulir cada función.", de: "Üblicherweise 8 bis 12 Wochen, in wöchentlichen Schritten. Sie können verkaufen, sobald Kauf und Bereitstellung bewiesen sind, bevor jede Funktion auspoliert ist." } },
  { question: { en: "Do I keep my payment processor and revenue?", fr: "Puis-je garder mon prestataire de paiement et mes revenus ?", es: "¿Conservo mi procesador de pagos y mis ingresos?", de: "Behalte ich meinen Zahlungsanbieter und meine Umsätze?" }, answer: { en: "Yes. The platform connects to the payment provider you choose and takes no cut on top of the processor fee. Owning the checkout is usually the whole reason to build.", fr: "Oui. La plateforme se connecte au prestataire de paiement que vous choisissez et ne prélève aucune commission au-dessus des frais de traitement. Posséder le checkout est généralement la raison même du développement.", es: "Sí. La plataforma se conecta al proveedor de pagos que elijas y no cobra comisión adicional a la del procesador. Tener el checkout propio suele ser la razón principal para desarrollar.", de: "Ja. Die Plattform verbindet sich mit dem Zahlungsanbieter Ihrer Wahl und nimmt keinen Anteil zusätzlich zur Zahlungsgebühr. Den Checkout zu besitzen ist meist der ganze Grund für den Aufbau." } },
  { question: { en: "Can you migrate my existing courses and students?", fr: "Pouvez-vous migrer mes cours et apprenants existants ?", es: "¿Podéis migrar mis cursos y alumnos actuales?", de: "Können Sie meine bestehenden Kurse und Lernenden migrieren?" }, answer: { en: "We export what your current tool allows, courses, media, and customer records, rebuild the flows that matter, and test buying, access, and refunds with real-looking data before anyone switches.", fr: "Nous exportons ce que votre outil actuel permet, cours, médias et dossiers clients, reconstruisons les parcours qui comptent et testons achat, accès et remboursement avec des données réalistes avant tout changement.", es: "Exportamos lo que permite tu herramienta actual, cursos, medios y registros de clientes, reconstruimos los flujos importantes y probamos compra, acceso y reembolsos con datos realistas antes de que nadie cambie.", de: "Wir exportieren, was Ihr aktuelles Tool zulässt, Kurse, Medien und Kundendaten, bauen die wichtigen Abläufe neu und testen Kauf, Zugriff und Rückerstattungen mit realistischen Daten, bevor jemand wechselt." } },
];

const schoolFaqs: ServicePage["faqs"] = [
  { question: { en: "How much does a school student portal cost?", fr: "Combien coûte un portail étudiant pour établissement scolaire ?", es: "¿Cuánto cuesta un portal de estudiantes para una escuela?", de: "Was kostet ein Schul- und Studierendenportal?" }, answer: { en: "SIS integration, the number of roles, parent access, gradebook needs, and legacy data migration move the number the most. We usually start with the student service causing the most friction, then expand from a stable base, and quote against that specific first release rather than a generic range.", fr: "L'intégration SIS, le nombre de rôles, l'accès parent, les besoins de carnet de notes et la migration des données historiques font le plus varier le budget. Nous commençons généralement par le service étudiant qui crée le plus de friction, puis étendons depuis une base stable et chiffrons cette première version précise plutôt qu'une fourchette générique.", es: "La integración con SIS, el número de roles, el acceso de familias, las necesidades de calificaciones y la migración de datos heredados son los factores que más mueven el presupuesto. Solemos empezar por el servicio estudiantil que más fricción causa, ampliamos desde una base estable y presupuestamos esa primera versión concreta en vez de un rango genérico.", de: "SIS-Integration, die Anzahl der Rollen, Elternzugang, Anforderungen an das Notenbuch und die Migration alter Daten beeinflussen den Preis am stärksten. Wir beginnen meist mit dem Studierendenservice, der die meiste Reibung verursacht, erweitern von einer stabilen Basis und bepreisen diese konkrete erste Version statt einer allgemeinen Spanne." } },
  { question: { en: "How long does it take to launch?", fr: "Combien de temps faut-il pour le lancement ?", es: "¿Cuánto tarda el lanzamiento?", de: "Wie lange dauert der Launch?" }, answer: { en: "About 8 to 12 weeks for a focused first release. The high-volume paths, sign-in, timetable, assignments, get built and validated first.", fr: "Environ 8 à 12 semaines pour une première version ciblée. Les parcours les plus utilisés, la connexion, l'emploi du temps et les devoirs sont développés et validés en premier.", es: "Unas 8 a 12 semanas para una primera versión enfocada. Primero se construyen y validan los flujos de mayor uso, inicio de sesión, horario y tareas.", de: "Etwa 8 bis 12 Wochen für eine fokussierte erste Version. Die volumenstarken Wege, Login, Stundenplan und Aufgaben werden zuerst gebaut und validiert." } },
  { question: { en: "Who owns and protects the student data?", fr: "Qui possède et protège les données étudiantes ?", es: "¿Quién es propietario y protege los datos de estudiantes?", de: "Wem gehören die Studierendendaten und wer schützt sie?" }, answer: { en: "Your institution controls the environment and the data-access model. We design permissions, audit needs, retention, and incident responsibilities with you, and document them before launch rather than after.", fr: "Votre établissement contrôle l'environnement et le modèle d'accès aux données. Nous concevons avec vous les permissions, besoins d'audit, conservation et responsabilités liées aux incidents, puis les documentons avant le lancement.", es: "Tu institución controla el entorno y el modelo de acceso a los datos. Diseñamos contigo permisos, necesidades de auditoría, retención y responsabilidades ante incidentes, y los documentamos antes del lanzamiento.", de: "Ihre Einrichtung kontrolliert die Umgebung und das Datenzugriffsmodell. Gemeinsam planen wir Berechtigungen, Audit-Anforderungen, Aufbewahrung und Verantwortlichkeiten bei Vorfällen und dokumentieren sie vor dem Launch." } },
  { question: { en: "Do we have to replace our SIS and LMS?", fr: "Devons-nous remplacer notre SIS et notre LMS ?", es: "¿Tenemos que sustituir nuestro SIS y LMS?", de: "Müssen wir unser SIS und LMS ersetzen?" }, answer: { en: "No, and replacing everything is often the riskiest first move. The SIS can stay the source of truth for enrolment and the LMS can keep course content, while the portal gives students, parents, and staff one front door through tested integrations.", fr: "Non, et tout remplacer est souvent le premier choix le plus risqué. Le SIS peut rester la source de référence pour les inscriptions et le LMS conserver les contenus, tandis que le portail offre aux étudiants, parents et équipes une entrée unique par des intégrations éprouvées.", es: "No, y reemplazarlo todo suele ser el primer paso más arriesgado. El SIS puede seguir siendo la fuente de referencia para las inscripciones y el LMS puede conservar los contenidos de cursos, mientras el portal ofrece a estudiantes, familias y personal una entrada única mediante integraciones probadas.", de: "Nein, und alles zu ersetzen ist oft der riskanteste erste Schritt. Das SIS kann die führende Quelle für Einschreibungen bleiben und das LMS die Kursinhalte behalten, während das Portal Studierenden, Eltern und Personal über geprüfte Integrationen einen gemeinsamen Einstieg bietet." } },
];

